    private void updateSources(){for(Spinner format:sourceFormats.values())if(format.isEnabled()==CaptureService.active())format.setEnabled(!CaptureService.active());if(System.currentTimeMillis()-lastMonitor>1000){lastMonitor=System.currentTimeMillis();monitors.refresh();}int allColor=CaptureService.active()?0xfff45b79:0xff938d9c;if(recordAll.getCurrentTextColor()!=allColor)recordAll.setTextColor(allColor);for(Map.Entry<String,Row> entry:sourceRows.entrySet()){CaptureService.Track saved=CaptureService.tracks.get(entry.getKey());boolean recording=CaptureService.active()&&saved!=null&&saved.running;CaptureService.Track t=recording?saved:monitors.get(entry.getKey());Row row=entry.getValue();int dot=recording?0xfff45b79:0xff938d9c;if(row.button.getCurrentTextColor()!=dot)row.button.setTextColor(dot);row.button.setContentDescription((recording?"Stop ":"Record ")+Source.get(entry.getKey()).title);row.wave.update(t);if(t!=null){setIfChanged(row.state,(recording?"RECORDING • ":"")+t.state);setIfChanged(row.stats,t.error.isEmpty()?String.format(Locale.US,"%.1f dBFS • peak %.0f%% • %,d frames",t.db,t.peak*100,t.frames):t.error);}else setIfChanged(row.state,"WAITING FOR MONITOR");}}
