        record=button(CaptureService.active()?"Stop & save session":"●  Record selected sources",ACCENT,()->{if(CaptureService.active())CaptureService.instance.stopSession();else startRecord(selected.toArray(new String[0]));});hero.addView(record);pause=button(CaptureService.paused?"Resume":"Pause",CARD,()->{if(CaptureService.active())CaptureService.instance.togglePause();});two(hero,pause,button("Add bookmark",CARD,()->{if(CaptureService.active())prompt("Bookmark label","",s->CaptureService.instance.mark(s));else toast("Start a session first");}));body.addView(hero);
        LinearLayout presets=card();presets.addView(text("CAPTURE PRESET",10,MUTED));String[] names={"Custom selection","Voice memo","Teams / app call","Carrier call","Carrier separated","Wi-Fi Calling probe","Media + microphone","Playback diagnostics"};Spinner spinner=spinner(names,0);spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(position>0){String[][] ids={{},{"mic"},{"mic","voice_playback"},{"voice_call"},{"uplink","downlink"},{"mic","voice_call","uplink","downlink","voice_playback","media"},{"media","mic"},{"media","game","voice_playback","navigation","assistant","alarm","notification"}};selected.clear();selected.addAll(Arrays.asList(ids[position]));saveSelection();for(Source s:Source.ALL)if(rows.containsKey(s.id))rows.get(s.id).selected.setChecked(selected.contains(s.id));}}});presets.addView(spinner);two(presets,button("Save preset",CARD,()->prompt("Preset name","My setup",this::savePreset)),button("Load preset",CARD,this::loadPreset));body.addView(presets);
