        section("ABOUT & SOURCE");LinearLayout about=card();about.addView(text("AudioScope 0.1.0 • experimental device build",16,INK));about.addView(text("Local capture and processing. No accounts, uploads, analytics, or cloud dependency. Network permission supports on-device ADB only. Use recordings where you have permission to record.",12,MUTED));about.addView(text("This software is an independently redesigned fork / edited derivative of capture and daemon components from CallVault and ShizuCallRecorder. GPLv3-or-later with upstream Section 7 terms. No warranty.",12,MUTED));about.addView(button("ShizuCallRecorder • original source",CARD,()->openUrl("https://github.com/kitsumed/ShizuCallRecorder")));about.addView(button("CallVault • capture reference",CARD,()->openUrl("https://github.com/madkongo/CallVault")));about.addView(button("Shevery • optional privilege manager",CARD,()->openUrl("https://github.com/HmnDev-Tech/shevery")));body.addView(about);
