    private boolean settingsEditable(){if(CaptureService.active()||CaptureService.instance!=null&&CaptureService.stopping){toast("Stop and finalize the session before changing setup or routing");return false;}return true;}
    private EditText input(String hint,String value,boolean numeric){EditText e=new EditText(this);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setTextSize(13);e.setSingleLine(true);e.setHint(hint);e.setText(value);e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(ACCENT));e.setInputType(numeric?android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED:android.text.InputType.TYPE_CLASS_TEXT);return e;}
    private Spinner spinner(String[] labels,int selected){Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels);s.setAdapter(adapter);s.setSelection(selected);return s;}
    private void toggle(LinearLayout c,String label,String detail,String key,boolean fallback){com.google.android.material.materialswitch.MaterialSwitch s=new com.google.android.material.materialswitch.MaterialSwitch(this);s.setText(label);s.setTextColor(INK);s.setTextSize(14);s.setPadding(0,dp(8),0,dp(6));s.setChecked(ScopeApp.prefs().getBoolean(key,fallback));s.setEnabled(!CaptureService.active());s.setThumbTintList(android.content.res.ColorStateList.valueOf(ACCENT));s.setOnCheckedChangeListener((v,b)->ScopeApp.prefs().edit().putBoolean(key,b).apply());c.addView(s);c.addView(text(detail,11,MUTED));}
    private void choice(LinearLayout c,String label,String[] labels,String key,int[] values,int fallback){c.addView(text(label,12,MUTED));int value=ScopeApp.prefs().getInt(key,fallback),index=0;for(int i=0;i<values.length;i++)if(values[i]==value)index=i;Spinner s=spinner(labels,index);s.setEnabled(!CaptureService.active());s.setOnItemSelectedListener(listener(position->{int old=ScopeApp.prefs().getInt(key,fallback);ScopeApp.prefs().edit().putInt(key,values[position]).apply();if(old!=values[position])disarmAfterFormatChange();}));c.addView(s);}
    private void stringChoice(LinearLayout c,String label,String[] labels,String key,String fallback){c.addView(text(label,12,MUTED));String value=ScopeApp.prefs().getString(key,fallback);int index=0;for(int i=0;i<labels.length;i++)if(labels[i].equals(value))index=i;Spinner s=spinner(labels,index);s.setEnabled(!CaptureService.active());s.setOnItemSelectedListener(listener(position->ScopeApp.prefs().edit().putString(key,labels[position]).apply()));c.addView(s);}
    private AdapterView.OnItemSelectedListener listener(java.util.function.IntConsumer action){return new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int p,long id){action.accept(p);}};}
    private void sourceSpinner(LinearLayout c,String label,String key,String fallback){c.addView(text(label,12,MUTED));String[] names=Source.ALL.stream().map(s->s.title).toArray(String[]::new);int index=0;for(int i=0;i<Source.ALL.size();i++)if(Source.ALL.get(i).id.equals(ScopeApp.prefs().getString(key,fallback)))index=i;Spinner s=spinner(names,index);s.setEnabled(!CaptureService.active());s.setOnItemSelectedListener(listener(p->ScopeApp.prefs().edit().putString(key,Source.ALL.get(p).id).apply()));c.addView(s);}
    private void numberSetting(LinearLayout c,String label,String key,int fallback,int min,int max){c.addView(text(label,12,MUTED));EditText e=input(label,String.valueOf(ScopeApp.prefs().getInt(key,fallback)),true);e.setEnabled(!CaptureService.active());e.setOnFocusChangeListener((v,focus)->{if(!focus){try{int n=Integer.parseInt(e.getText().toString());if(n<min||n>max)throw new NumberFormatException();ScopeApp.prefs().edit().putInt(key,n).apply();if(key.equals("uidFilter"))disarmAfterFormatChange();}catch(Exception ex){e.setText(String.valueOf(ScopeApp.prefs().getInt(key,fallback)));toast("Use a value from "+min+" to "+max);}}});c.addView(e);}
    private void disarmAfterFormatChange(){ScopeApp.IO.execute(()->{try{if(ScopeApp.bridge!=null)ScopeApp.bridge.disarm();}catch(Exception ignored){}});}
    private void prompt(String title,String initial,java.util.function.Consumer<String> action){EditText e=input(title,initial,false);new AlertDialog.Builder(this).setTitle(title).setView(e).setPositiveButton("Save",(d,w)->{String s=e.getText().toString().trim();if(!s.isEmpty())action.accept(s);}).setNegativeButton("Cancel",null).show();}
    private void savePreset(String name){if(!settingsEditable())return;try{JSONObject j=new JSONObject();j.put("sources",new JSONArray(selected));JSONObject settings=new JSONObject();for(Map.Entry<String,?> e:ScopeApp.prefs().getAll().entrySet()){String k=e.getKey();if(k.equals("rate")||k.equals("channels")||k.equals("uidFilter")||k.equals("codec")||k.equals("bitrate")||k.equals("raw")||k.equals("stereo")||k.equals("mix")||k.equals("mka")||k.startsWith("route")||k.startsWith("gain_")||k.startsWith("mute_")||k.startsWith("format_"))settings.put(k,e.getValue());}j.put("settings",settings);JSONObject all=new JSONObject(ScopeApp.prefs().getString("presets","{}"));all.put(name,j);ScopeApp.prefs().edit().putString("presets",all.toString()).apply();toast("Saved "+name);}catch(Exception e){toast(e.toString());}}
    private void loadPreset(){if(!settingsEditable())return;try{JSONObject all=new JSONObject(ScopeApp.prefs().getString("presets","{}"));List<String> names=new ArrayList<>();all.keys().forEachRemaining(names::add);if(names.isEmpty()){toast("Save a preset first");return;}new AlertDialog.Builder(this).setTitle("Load capture preset").setItems(names.toArray(new String[0]),(d,w)->{try{JSONObject j=all.getJSONObject(names.get(w));selected.clear();JSONArray a=j.getJSONArray("sources");for(int i=0;i<a.length();i++)selected.add(a.getString(i));saveSelection();JSONObject prefs=j.getJSONObject("settings");SharedPreferences.Editor edit=ScopeApp.prefs().edit();Iterator<String> keys=prefs.keys();while(keys.hasNext()){String key=keys.next();Object v=prefs.get(key);if(v instanceof Boolean)edit.putBoolean(key,(Boolean)v);else if(v instanceof Integer)edit.putInt(key,(Integer)v);else if(v instanceof Number)edit.putFloat(key,((Number)v).floatValue());else edit.putString(key,v.toString());}edit.apply();disarmAfterFormatChange();render();}catch(Exception e){toast(e.toString());}}).show();}catch(Exception e){toast(e.toString());}}
    private void showText(String title,String content){ScrollView s=new ScrollView(this);TextView t=text(content,12,INK);t.setPadding(dp(16),dp(12),dp(16),dp(12));t.setTextIsSelectable(true);s.addView(t);new AlertDialog.Builder(this).setTitle(title).setView(s).setPositiveButton("Close",null).show();}
    private void setIfChanged(TextView view,CharSequence value){if(!view.getText().toString().contentEquals(value))view.setText(value);}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private void openUrl(String url){startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}
